(()=>{document.addEventListener("DOMContentLoaded",()=>{let e=document.querySelector("[data-ws-mobile-sales]");if(!e)return;let i=e.querySelector("[data-ws-mobile-add]"),n=document.querySelector("form.cart");if(!i||!n)return;let o=()=>{let t=n.getBoundingClientRect(),r=t.top<window.innerHeight&&t.bottom>0;e.classList.toggle("is-visible",!r)};i.addEventListener("click",()=>{let t=n.querySelector(".single_add_to_cart_button");t&&t.click()}),window.addEventListener("scroll",o,{passive:!0}),window.addEventListener("resize",o),o()});})();
